import React, { useState } from "react";

const PredictionPage = () => {
  const [inputData, setInputData] = useState({
    age: "",
    gender: "",
    hypertension: "",
    heart_disease: "",
    marital_status: "",
    work_type: "",
    residence_type: "",
    avg_glucose_level: "",
    bmi: "",
    smoking_status: "",
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setInputData((prevData) => ({
      ...prevData,
      [name]: value,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const { age, gender, hypertension, heart_disease, marital_status, work_type, residence_type, avg_glucose_level, bmi, smoking_status } = inputData;

    const modelType = "rf"; // You can change the model type as needed ("rf", "svm", or "cnn")
    
    const data = {
      inputData: [
        parseFloat(age),
        gender === "Male" ? 0 : 1, // Encode gender as 0 for Male and 1 for Female
        parseInt(hypertension),
        parseInt(heart_disease),
        marital_status === "Single" ? 0 : marital_status === "Married" ? 1 : 2, // Encode marital status
        work_type === "Private" ? 0 : work_type === "Self-employed" ? 1 : work_type === "Govt_job" ? 2 : work_type === "Never_worked" ? 3 : 4, // Encode work type
        residence_type === "Urban" ? 0 : 1, // Encode residence type as 0 for Urban and 1 for Rural
        parseFloat(avg_glucose_level),
        parseFloat(bmi),
        smoking_status === "formerly smoked" ? 0 : smoking_status === "never smoked" ? 1 : 2, // Encode smoking status
      ],
      modelType: modelType,
    };

    try {
      const response = await fetch("http://localhost:5000/predict", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(data),
      });
      const result = await response.json();
      alert(`Prediction: ${result.prediction === 1 ? "Alzheimer's detected" : "No Alzheimer's detected"}`);
    } catch (error) {
      console.error("Error during prediction:", error);
    }
  };

  return (
    <div>
      <h2>Predict Alzheimer's Disease</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label>Age:</label>
          <input type="number" name="age" value={inputData.age} onChange={handleChange} required />
        </div>
        <div>
          <label>Gender:</label>
          <select name="gender" value={inputData.gender} onChange={handleChange} required>
            <option value="">Select Gender</option>
            <option value="Male">Male</option>
            <option value="Female">Female</option>
          </select>
        </div>
        <div>
          <label>Hypertension:</label>
          <input type="number" name="hypertension" value={inputData.hypertension} onChange={handleChange} required />
        </div>
        <div>
          <label>Heart Disease:</label>
          <input type="number" name="heart_disease" value={inputData.heart_disease} onChange={handleChange} required />
        </div>
        <div>
          <label>Marital Status:</label>
          <select name="marital_status" value={inputData.marital_status} onChange={handleChange} required>
            <option value="">Select Marital Status</option>
            <option value="Single">Single</option>
            <option value="Married">Married</option>
            <option value="Divorced">Divorced</option>
          </select>
        </div>
        <div>
          <label>Work Type:</label>
          <select name="work_type" value={inputData.work_type} onChange={handleChange} required>
            <option value="">Select Work Type</option>
            <option value="Private">Private</option>
            <option value="Self-employed">Self-employed</option>
            <option value="Govt_job">Govt_job</option>
            <option value="Never_worked">Never_worked</option>
            <option value="Children">Children</option>
          </select>
        </div>
        <div>
          <label>Residence Type:</label>
          <select name="residence_type" value={inputData.residence_type} onChange={handleChange} required>
            <option value="">Select Residence Type</option>
            <option value="Urban">Urban</option>
            <option value="Rural">Rural</option>
          </select>
        </div>
        <div>
          <label>Average Glucose Level:</label>
          <input type="number" name="avg_glucose_level" value={inputData.avg_glucose_level} onChange={handleChange} required />
        </div>
        <div>
          <label>BMI:</label>
          <input type="number" name="bmi" value={inputData.bmi} onChange={handleChange} required />
        </div>
        <div>
          <label>Smoking Status:</label>
          <select name="smoking_status" value={inputData.smoking_status} onChange={handleChange} required>
            <option value="">Select Smoking Status</option>
            <option value="formerly smoked">Formerly smoked</option>
            <option value="never smoked">Never smoked</option>
            <option value="smokes">Smokes</option>
          </select>
        </div>
        <button type="submit">Submit</button>
      </form>
    </div>
  );
};

export default PredictionPage;
